package com.friendinneed.routine; import com.friendinneed.consent.*;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profiles/{profileId}/routines") public class RoutineController{private final RoutineService service;private final ConsentService consent;public RoutineController(RoutineService s,ConsentService c){service=s;consent=c;}private void allowed(UUID p){if(!consent.isEnabled(p,IntegrationType.SMART_HOME))throw new org.springframework.security.access.AccessDeniedException("Smart home consent is required");}@GetMapping List<Routine> list(@PathVariable UUID profileId){allowed(profileId);return service.list(profileId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) Routine create(@PathVariable UUID profileId,@RequestBody Request r){allowed(profileId);return service.create(profileId,r.triggerPhrase(),r.steps());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID profileId,@PathVariable UUID id){allowed(profileId);service.delete(profileId,id);}record Request(String triggerPhrase,List<Map<String,Object>> steps){}}
